android.extraProguardRules:
# --- Kotlin reflection ------------------------------------------------------
# Expo resolves module and view-prop types through kotlin-reflect at runtime.
# That needs the generic signatures and @kotlin.Metadata annotations intact —
# without them prop binding dies with "Unresolved class: <type>".
-keepattributes Signature,InnerClasses,EnclosingMethod
-keepattributes RuntimeVisibleAnnotations,RuntimeVisibleParameterAnnotations
-keepattributes AnnotationDefault
-keep class kotlin.Metadata { *; }
-keep class kotlin.reflect.jvm.internal.** { *; }
-dontwarn kotlin.**

# --- Hermes -----------------------------------------------------------------
# The JS engine is reached entirely through JNI, so R8 sees no callers.
-keep class com.facebook.hermes.unicode.** { *; }
-keep class com.facebook.jni.** { *; }

# --- Native view managers ---------------------------------------------------
# These libraries ship no consumer rules of their own. Their ViewManagers are
# resolved by name from JS, so keep the class names intact.
-keep class com.swmansion.rnscreens.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
-keep class com.th3rdwave.safeareacontext.** { *; }

# --- Crash reports ----------------------------------------------------------
# Keep line numbers so release stack traces stay readable, but rename the
# source file attribute so it doesn't leak original filenames.
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile

# --- Logging ----------------------------------------------------------------
# Strip verbose/debug logging from release builds.
-assumenosideeffects class android.util.Log {
    public static *** v(...);
    public static *** d(...);
}
